import React,{useId} from 'react';
export function MemoryCreationFields({kind,draft,change}){
 const id=useId(),values=draft.values||{},set=(key,value)=>change(old=>({...old,values:{...old.values,[key]:value}}));
 return <section className="creation-profile"><h3>{kind==='character_card'?'角色基本资料':'世界条目分类'}</h3><p className="muted">以下均可选；创建时与自由详述一起保存，之后可在资料字段中补充。</p><div className="structure-fields">{kind==='character_card'?<><label>性别说明<input aria-label="新角色性别" value={values['character:gender']||''} placeholder="按角色设定填写" onChange={e=>set('character:gender',e.target.value)}/></label><label>身份／职业<input aria-label="新角色身份" value={values['character:occupation']||''} placeholder="如：学生、治疗师、守门人" onChange={e=>set('character:occupation',e.target.value)}/></label><label>年龄说明<input aria-label="新角色年龄" value={values['character:age']||''} onChange={e=>set('character:age',e.target.value)}/></label><label>所属组织<input aria-label="新角色所属组织" value={values['character:organization']||''} onChange={e=>set('character:organization',e.target.value)}/></label></>:<><label>类别<input aria-label="新世界条目类别" list={id} value={values['world:category']||''} placeholder="地点、组织、物品…也可自定义" onChange={e=>set('world:category',e.target.value)}/><datalist id={id}>{['地点','组织','物品','规则','种族','历史','其他'].map(t=><option key={t} value={t}/>)}</datalist></label><label>所属区域／组织<input aria-label="新世界条目区域" value={values['world:region']||''} onChange={e=>set('world:region',e.target.value)}/></label><label>适用时期<input aria-label="新世界条目时期" value={values['world:period']||''} onChange={e=>set('world:period',e.target.value)}/></label></>}<label>别名<input aria-label="新资料别名" value={draft.aliasesText||''} placeholder="多个别名用逗号分隔" onChange={e=>change(old=>({...old,aliasesText:e.target.value}))}/></label></div></section>;
}
